-- STAGING-only compatibility gate: expose the existing per-user Bridge role resolver
-- through a SECURITY INVOKER PostgREST wrapper. No role is accepted from caller input.
-- Also remove the legacy single-active-organization constraint so memberships
-- are unique per (organization_id, user_id), not globally per user.

create or replace function public.bridge_current_internal_role()
returns text
language sql
stable
security invoker
set search_path = pg_catalog
as $function$
  select bridge_private.current_internal_role();
$function$;

revoke all on function public.bridge_current_internal_role() from public, anon, authenticated;
grant execute on function public.bridge_current_internal_role() to authenticated;

comment on function public.bridge_current_internal_role() is
  'Authenticated-only, invoker wrapper returning the verified current user internal role; underlying resolver remains in bridge_private.';

drop index if exists public.bridge_organization_memberships_one_active_org_per_user;

-- Shared Bridge Testing DB only.
-- Add Loop runtime tables aligned to the existing STAGING schema:
-- loop_titles.id is TEXT; Bridge publication states are uppercase.
-- No demo titles, subscriptions, payments, plans, or entitlements are seeded.
-- All runtime tables remain server-only: RLS enabled, no browser grants/policies.

create table if not exists public.loop_plans (
  id uuid primary key default gen_random_uuid(),
  plan_key text not null unique,
  name text not null,
  price_paise bigint not null check (price_paise >= 0),
  duration_days integer not null check (duration_days > 0),
  is_active boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.loop_subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete restrict,
  plan_key text not null,
  status text not null default 'pending'
    check (status in ('pending','active','cancelled','expired','refunded')),
  started_at timestamptz,
  expires_at timestamptz,
  razorpay_subscription_id text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (expires_at is null or started_at is null or expires_at > started_at)
);

create table if not exists public.loop_user_tvod_entitlements (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete restrict,
  title_id text not null references public.loop_titles(id) on delete restrict,
  access_type text not null check (access_type in ('RENTAL','PURCHASE')),
  purchased_at timestamptz not null,
  started_watching_at timestamptz,
  expires_at timestamptz,
  payment_transaction_id text not null unique,
  status text not null default 'ACTIVE'
    check (status in ('ACTIVE','REFUNDED','REVOKED','EXPIRED')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id,title_id,access_type),
  check (expires_at is null or expires_at > purchased_at)
);

create table if not exists public.loop_payment_events (
  id uuid primary key default gen_random_uuid(),
  event_id text not null unique,
  event_name text not null,
  razorpay_payment_id text,
  user_id uuid references auth.users(id) on delete set null,
  status text not null default 'received'
    check (status in ('received','processed','refunded','failed','reconciliation_required')),
  payload jsonb not null default '{}'::jsonb,
  received_at timestamptz not null default now(),
  processed_at timestamptz
);

create table if not exists public.loop_watch_progress (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  title_id text not null references public.loop_titles(id) on delete cascade,
  position_seconds numeric(12,2) not null default 0 check (position_seconds >= 0),
  duration_seconds numeric(12,2) not null default 0 check (duration_seconds >= 0),
  completed boolean not null default false,
  updated_at timestamptz not null default now(),
  unique (user_id,title_id)
);

create table if not exists public.loop_media_migration_queue (
  id uuid primary key default gen_random_uuid(),
  bridge_title_id text not null references public.bridge_titles(id) on delete restrict,
  loop_title_id text not null references public.loop_titles(id) on delete restrict,
  bridge_asset_id text not null references public.bridge_assets(id) on delete restrict,
  status text not null default 'PENDING'
    check (status in ('PENDING','PROCESSING','VERIFIED','FAILED','CANCELLED')),
  attempt_count integer not null default 0 check (attempt_count >= 0),
  lease_owner text,
  lease_expires_at timestamptz,
  last_error text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  processed_at timestamptz,
  unique (bridge_asset_id)
);

create index if not exists loop_subscriptions_user_status_idx
  on public.loop_subscriptions(user_id,status,expires_at desc);
create index if not exists loop_tvod_entitlements_user_status_idx
  on public.loop_user_tvod_entitlements(user_id,status,expires_at desc);
create index if not exists loop_payment_events_payment_id_idx
  on public.loop_payment_events(razorpay_payment_id);
create index if not exists loop_watch_progress_user_updated_idx
  on public.loop_watch_progress(user_id,updated_at desc);
create index if not exists loop_media_migration_queue_status_idx
  on public.loop_media_migration_queue(status,created_at);

alter table public.loop_plans enable row level security;
alter table public.loop_subscriptions enable row level security;
alter table public.loop_user_tvod_entitlements enable row level security;
alter table public.loop_payment_events enable row level security;
alter table public.loop_watch_progress enable row level security;
alter table public.loop_media_migration_queue enable row level security;

revoke all on table
  public.loop_plans,
  public.loop_subscriptions,
  public.loop_user_tvod_entitlements,
  public.loop_payment_events,
  public.loop_watch_progress,
  public.loop_media_migration_queue
from public, anon, authenticated;

grant select, insert, update, delete on table
  public.loop_plans,
  public.loop_subscriptions,
  public.loop_user_tvod_entitlements,
  public.loop_payment_events,
  public.loop_watch_progress,
  public.loop_media_migration_queue
to service_role;

comment on table public.loop_plans is 'Server-only Loop subscription plan catalogue; no active plans are seeded by the STAGING compatibility migration.';
comment on table public.loop_subscriptions is 'Server-only Loop subscription records. Consumer subscription sales remain disabled until separately approved.';
comment on table public.loop_user_tvod_entitlements is 'Server-only TVOD entitlements; title_id is TEXT to match the canonical STAGING loop_titles primary key.';
comment on table public.loop_payment_events is 'Server-only idempotent Razorpay/payment event ledger; never writable from browser roles.';
comment on table public.loop_watch_progress is 'Server-only Loop watch progress; browser roles have no direct table grants.';
comment on table public.loop_media_migration_queue is 'Server-only queue linking verified Bridge assets to Loop titles; no media keys are accepted from consumers.';

create or replace function public.loop_fulfill_captured_rental(
  p_payment_id text,
  p_order_id text,
  p_user_id uuid,
  p_title_id text,
  p_purchased_at timestamptz,
  p_expires_at timestamptz
) returns jsonb
language plpgsql
security invoker
set search_path = ''
as $function$
declare
  existing public.loop_payment_events%rowtype;
  entitlement public.loop_user_tvod_entitlements%rowtype;
  payload jsonb;
  title_language text;
begin
  if nullif(p_payment_id,'') is null
     or nullif(p_order_id,'') is null
     or p_user_id is null
     or nullif(p_title_id,'') is null
     or p_purchased_at is null
     or p_expires_at is null
     or p_purchased_at > pg_catalog.now() + interval '1 minute'
     or p_expires_at <> p_purchased_at + interval '48 hours' then
    raise exception 'Invalid rental inputs';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('payment:' || p_payment_id, 0));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_user_id::text || ':' || p_title_id, 0));

  select * into existing
  from public.loop_payment_events
  where event_id = 'tvod:' || p_payment_id
  for update;

  payload := pg_catalog.jsonb_build_object(
    'order_id',p_order_id,
    'title_id',p_title_id,
    'purchased_at',p_purchased_at,
    'expires_at',p_expires_at
  );

  if found then
    if existing.user_id is distinct from p_user_id
       or existing.razorpay_payment_id is distinct from p_payment_id
       or existing.payload->>'order_id' is distinct from p_order_id
       or existing.payload->>'title_id' is distinct from p_title_id then
      raise exception 'Payment identity mismatch';
    end if;
    if existing.status = 'refunded' then
      raise exception 'Refunded payment cannot grant an entitlement';
    end if;
    if existing.status <> 'processed' then
      raise exception 'Payment reconciliation required';
    end if;
    return pg_catalog.jsonb_build_object(
      'deduplicated',true,
      'status',existing.status,
      'expires_at',existing.payload->>'expires_at'
    );
  end if;

  select t.language into title_language
  from public.loop_titles t
  join public.bridge_loop_publications p
    on p.loop_title_id = t.id
   and p.bridge_title_id = t.bridge_title_id
  where t.id = p_title_id
    and t.status in ('APPROVED','PUBLISHED')
    and t.is_listed = true
    and t.is_published = true
    and t.access_tier = 'TVOD'
    and p.destination = 'CRAYONS_LOOP'
    and p.authorization_status = 'AUTHORIZED'
    and p.revoked_at is null
    and p.approved_at is not null
    and p.window_start is not null
    and p.window_end is not null
    and p.window_start <= pg_catalog.now()
    and p.window_end > pg_catalog.now()
    and 'WORLDWIDE' = any(p.territories)
    and 'TVOD' = any(p.exploitation_models)
    and exists (
      select 1 from pg_catalog.unnest(p.languages) as allowed(language)
      where pg_catalog.upper(pg_catalog.btrim(allowed.language)) =
            pg_catalog.upper(pg_catalog.btrim(t.language))
    )
  limit 1;

  if not found or title_language is null then
    raise exception 'Publication unavailable';
  end if;

  select * into entitlement
  from public.loop_user_tvod_entitlements
  where user_id = p_user_id
    and title_id = p_title_id
    and access_type = 'RENTAL'
  for update;

  if found and entitlement.purchased_at >= p_purchased_at
     and entitlement.payment_transaction_id <> p_payment_id then
    raise exception 'Newer entitlement requires reconciliation';
  end if;

  if found and entitlement.payment_transaction_id = p_payment_id
     and entitlement.status <> 'ACTIVE' then
    raise exception 'Revoked entitlement requires reconciliation';
  end if;

  insert into public.loop_user_tvod_entitlements(
    user_id,title_id,access_type,purchased_at,expires_at,payment_transaction_id,status
  ) values (
    p_user_id,p_title_id,'RENTAL',p_purchased_at,p_expires_at,p_payment_id,'ACTIVE'
  )
  on conflict(user_id,title_id,access_type) do update
    set purchased_at = excluded.purchased_at,
        expires_at = excluded.expires_at,
        payment_transaction_id = excluded.payment_transaction_id,
        status = excluded.status,
        updated_at = pg_catalog.now();

  insert into public.loop_payment_events(
    event_id,event_name,razorpay_payment_id,user_id,status,payload,processed_at
  ) values (
    'tvod:' || p_payment_id,'tvod_fulfilled',p_payment_id,p_user_id,'processed',payload,pg_catalog.now()
  );

  return pg_catalog.jsonb_build_object(
    'type','TVOD',
    'title_id',p_title_id,
    'access_type','RENTAL',
    'status','ACTIVE',
    'expires_at',p_expires_at
  );
end
$function$;

revoke all on function public.loop_fulfill_captured_rental(text,text,uuid,text,timestamptz,timestamptz)
from public, anon, authenticated;
grant execute on function public.loop_fulfill_captured_rental(text,text,uuid,text,timestamptz,timestamptz)
to service_role;

create or replace function public.loop_refund_captured_rental(
  p_payment_id text,
  p_refund_id text
) returns jsonb
language plpgsql
security invoker
set search_path = ''
as $function$
declare
  existing public.loop_payment_events%rowtype;
begin
  if nullif(p_payment_id,'') is null or nullif(p_refund_id,'') is null then
    raise exception 'Refund identity missing';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('payment:' || p_payment_id, 0));

  select * into existing
  from public.loop_payment_events
  where event_id = 'tvod:' || p_payment_id
  for update;

  if not found then
    insert into public.loop_payment_events(
      event_id,event_name,razorpay_payment_id,status,payload,processed_at
    ) values (
      'tvod:' || p_payment_id,'tvod_refunded',p_payment_id,'refunded',
      pg_catalog.jsonb_build_object('refund_id',p_refund_id),pg_catalog.now()
    );
    return pg_catalog.jsonb_build_object('processed',true,'refund_before_capture',true);
  end if;

  if existing.razorpay_payment_id is distinct from p_payment_id then
    raise exception 'Refund payment identity mismatch';
  end if;

  update public.loop_user_tvod_entitlements
  set status = 'REFUNDED', updated_at = pg_catalog.now()
  where payment_transaction_id = p_payment_id;

  update public.loop_payment_events
  set status = 'refunded',
      payload = existing.payload || pg_catalog.jsonb_build_object('refund_id',p_refund_id),
      processed_at = pg_catalog.now()
  where id = existing.id;

  return pg_catalog.jsonb_build_object('processed',true,'payment_id',p_payment_id,'refund_id',p_refund_id);
end
$function$;

revoke all on function public.loop_refund_captured_rental(text,text) from public, anon, authenticated;
grant execute on function public.loop_refund_captured_rental(text,text) to service_role;

-- Explicitly mark every currently server-only RLS table as deny-by-default
-- for browser roles. Existing authenticated policies on the approved workspace
-- tables are preserved. No table is granted to anon/authenticated.
do $block$
declare
  r record;
begin
  for r in
    select n.nspname, c.relname
    from pg_catalog.pg_class c
    join pg_catalog.pg_namespace n on n.oid = c.relnamespace
    where n.nspname in ('public','bridge_private')
      and c.relkind = 'r'
      and c.relrowsecurity
      and not exists (
        select 1
        from pg_catalog.pg_policies p
        where p.schemaname = n.nspname
          and p.tablename = c.relname
      )
  loop
    execute pg_catalog.format(
      'create policy %I on %I.%I for all to anon, authenticated using (false) with check (false)',
      'deny_browser_access', r.nspname, r.relname
    );
  end loop;
end
$block$;

-- Remove broad default service_role extras on the six newly added Loop tables.
revoke all on table
  public.loop_plans,
  public.loop_subscriptions,
  public.loop_user_tvod_entitlements,
  public.loop_payment_events,
  public.loop_watch_progress,
  public.loop_media_migration_queue
from service_role;

grant select, insert, update, delete on table
  public.loop_plans,
  public.loop_subscriptions,
  public.loop_user_tvod_entitlements,
  public.loop_payment_events,
  public.loop_watch_progress,
  public.loop_media_migration_queue
to service_role;

-- Authenticated viewers may manage only their own watch progress.
-- No anonymous access; payment, subscription, identity and media queue tables remain server-only.
revoke all on table public.loop_watch_progress from anon, authenticated;
grant select, insert, update on table public.loop_watch_progress to authenticated;

create policy loop_watch_progress_select_own
  on public.loop_watch_progress
  for select to authenticated
  using ((select auth.uid()) = user_id);

create policy loop_watch_progress_insert_own
  on public.loop_watch_progress
  for insert to authenticated
  with check ((select auth.uid()) = user_id);

create policy loop_watch_progress_update_own
  on public.loop_watch_progress
  for update to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);
